import requests
import asyncio
import subprocess

import asyncWebAPI

import os
import time
import threading
from playwright.sync_api import sync_playwright

chrome_path = os.path.expandvars(
    r"%LOCALAPPDATA%\Google\Chrome\Application\chrome.exe"
)

not_Answers = ("Searching the web", "None")


class chatgptAPI():
    def __init__(self, headless=False):
        self.headless = headless
        self.browser = None
        self.page = None
        self.ready = False


    async def asleep(self, time=1000):
        await self.page.wait_for_timeout(time)


    async def say(self, msg):
        page = self.page
        textarea = await page.query_selector("#mobile-composer-prompt")
    
        await textarea.focus()
        await textarea.fill(msg)
        await textarea.dispatch_event("input", {"bubbles": True})

        await page.locator('button[data-composer-submit][aria-label="Send message"]').click()
        
        
        
    async def getMessages(self) -> str:
        rvalue = str()
        
        
        await self.page.wait_for_selector("li[data-message-role]")
        
        # Target messages using stable data attributes instead of changing classes
        message_elements = self.page.locator("li[data-message-role]")
        count = await message_elements.count()
        #print(f"Found {count} messages.\n")

        for i in range(count):
            msg = message_elements.nth(i)
            role = await msg.get_attribute("data-message-role")  # 'user' or 'assistant'

            # Select the text container based on the sender role
            if role == "user":
                continue
                text_element = msg.locator("[data-user-message-copy]")
            else:
                text_element = msg.locator("[data-assistant-markdown]")

            # Extract text safely
            if await text_element.count() > 0:
                content = (await text_element.inner_text()).strip()
                #print(f"[{role.upper()}] {content}\n")
                rvalue = content
        return rvalue
            
            

    async def ask(self, question, printing=False, better_prompt=True, tries=30, delay_time=1000, retry_time = 100, starter="!") -> str:
        if not self.ready: return ""

        if better_prompt:
            question = f"Answer as shortly and simply as possible. Also your answer must start with '{starter}'. " + question
        
        await self.say(question)
        
        await self.page.wait_for_timeout(delay_time)
        answer = str()
        
        for i in range(tries):
            await self.asleep(retry_time)

            try:
                answer = await self.getMessages()

                if answer:
                    if answer[0] == starter:
                        answer = answer[len(starter):]
                        break

            except Exception:
                pass
        if printing:
            print("AI: " + answer)
        return answer
                
                
                        
                        

    
    async def start(self):
        self.browser = await asyncWebAPI.AsyncChrome(
            chrome_path,
            headless=self.headless
        ).__aenter__()

        self.page = await self.browser.new_page(locale="en-US")

        await self.page.goto(
            "https://chatgpt.com",
            timeout=40000
        )

        self.ready = True
        print("ready")
    '''

    async def start(self):
        self.browser = asyncWebAPI.AsyncChrome(
            chrome_path,
            headless=self.headless
        )

        await self.browser.__aenter__()

        self.page = await self.browser.new_page(locale="en-US")

        await self.page.goto(
            "https://chatgpt.com",
            timeout=40000
        )

        self.ready = True
        print("ready")
    '''

    async def close(self):
        if self.browser:
            await self.browser.__aexit__(None, None, None)
            self.browser = None
            self.page = None
            self.ready = False
            

#asyncio.run(main())
async def main():
    ai = chatgptAPI()
    await ai.start()

    for i in range(10):
        answer = await ai.ask(input("ask something: "), printing=True)

    await ai.asleep(1000000)

    await ai.close()


asyncio.run(main())





